function solve(n, k) {
  function countPrefix(prefix, n) {
    let total = 0, first = prefix, last = prefix;
    while (first <= n) {
      total += Math.min(n, last) - first + 1;
      first *= 10;
      last = last * 10 + 9;
    }
    return total;
  }
  let cur = 1;
  k--;
  while (k > 0) {
    const cnt = countPrefix(cur, n);
    if (cnt <= k) { k -= cnt; cur++; }
    else { k--; cur *= 10; }
  }
  return cur;
}
